import numpy as np, random, ot, scipy.optimize as opt

def test_once(n, seed):
    random.seed(seed); np.random.seed(seed)
    a=ot.utils.unif(n)
    b=ot.utils.unif(n)
    M=ot.dist(np.random.rand(n,2), np.random.rand(n,2))
    G_ref=ot.lp.emd(a,b,M, check_marginals=False)
    row,col=opt.linear_sum_assignment(M)
    G=np.zeros_like(M)
    G[row,col]=1.0/n
    return np.allclose(G_ref, G)

for n in [5,6,7,8,9,10,20,30,50,100]:
    good=True
    for seed in range(200):
        if not test_once(n, seed):
            print('fail', n, seed); good=False; break
    print(n, 'good' if good else 'fail')
